#include "game/ScriptBindings.hpp"

#include <string>

#include "ecs/components/Transform.hpp"
#include "game/Components.hpp"
#include "input/InputState.hpp"
#include "input/scripting/InputScripting.hpp"
#include "render/api/components/CameraComponent.hpp"
#include "scripting/ComponentBinder.hpp"
#include "scripting/ScriptSystem.hpp"
#include "scripting/WrenVM.hpp"

namespace rlss::game {

namespace {

/** @brief Interprets the class generated by a binder in the components module. */
template <typename Binder>
bool define(sq::scripting::WrenVM& vm, const Binder& binder) {
    return vm.interpret(COMPONENTS_MODULE, binder.generateWrenClass()).has_value();
}

}  // namespace

bool registerComponentClasses(sq::scripting::WrenVM& vm) {
    const std::string module(COMPONENTS_MODULE);
    bool ok = true;

    sq::scripting::ComponentBinder<sq::ecs::Transform> transform(vm, module, "Transform");
    transform.property<&sq::ecs::Transform::x>("x")
        .property<&sq::ecs::Transform::y>("y")
        .property<&sq::ecs::Transform::rotation>("rotation")
        .property<&sq::ecs::Transform::scaleX>("scaleX")
        .property<&sq::ecs::Transform::scaleY>("scaleY");
    ok = define(vm, transform) && ok;

    sq::scripting::ComponentBinder<sq::input::InputState> controls(vm, module, "Controls");
    controls.property<&sq::input::InputState::playerIndex>("playerIndex");
    ok = define(vm, controls) && ok;

    sq::scripting::ComponentBinder<ArenaShape> arena(vm, module, "ArenaShape");
    arena.property<&ArenaShape::left>("left")
        .property<&ArenaShape::top>("top")
        .property<&ArenaShape::right>("right")
        .property<&ArenaShape::bottom>("bottom")
        .property<&ArenaShape::cornerRadius>("cornerRadius")
        .property<&ArenaShape::goalTop>("goalTop")
        .property<&ArenaShape::goalBottom>("goalBottom")
        .property<&ArenaShape::goalDepth>("goalDepth")
        .property<&ArenaShape::goalCornerRadius>("goalCornerRadius");
    ok = define(vm, arena) && ok;

    sq::scripting::ComponentBinder<CarParts> parts(vm, module, "CarParts");
    parts.property<&CarParts::body>("body")
        .property<&CarParts::cabin>("cabin")
        .property<&CarParts::rearWheel>("rearWheel")
        .property<&CarParts::frontWheel>("frontWheel")
        .property<&CarParts::headlight>("headlight")
        .property<&CarParts::flame>("flame")
        .property<&CarParts::gaugeBack>("gaugeBack")
        .property<&CarParts::gaugeFill>("gaugeFill")
        .property<&CarParts::flash>("flash");
    ok = define(vm, parts) && ok;

    sq::scripting::ComponentBinder<CarStatus> status(vm, module, "CarStatus");
    status.property<&CarStatus::boost>("boost")
        .property<&CarStatus::boosting>("boosting")
        .property<&CarStatus::placeAtKickoff>("placeAtKickoff")
        .property<&CarStatus::flipReset>("flipReset");
    ok = define(vm, status) && ok;

    sq::scripting::ComponentBinder<CarCues> carCues(vm, module, "CarCues");
    carCues.property<&CarCues::jumps>("jumps")
        .property<&CarCues::jumpKind>("jumpKind")
        .property<&CarCues::impacts>("impacts")
        .property<&CarCues::impactSpeed>("impactSpeed");
    ok = define(vm, carCues) && ok;

    sq::scripting::ComponentBinder<BallCues> ballCues(vm, module, "BallCues");
    ballCues.property<&BallCues::hits>("hits")
        .property<&BallCues::hitSpeed>("hitSpeed")
        .property<&BallCues::bounces>("bounces")
        .property<&BallCues::bounceSpeed>("bounceSpeed");
    ok = define(vm, ballCues) && ok;

    sq::scripting::ComponentBinder<BallPart> ballPart(vm, module, "BallPart");
    ballPart.property<&BallPart::parent>("parent")
        .property<&BallPart::offsetX>("offsetX")
        .property<&BallPart::offsetY>("offsetY")
        .property<&BallPart::angle>("angle")
        .property<&BallPart::spins>("spins")
        .property<&BallPart::glow>("glow");
    ok = define(vm, ballPart) && ok;

    sq::scripting::ComponentBinder<ShotGlow> glow(vm, module, "ShotGlow");
    glow.property<&ShotGlow::shot>("shot");
    ok = define(vm, glow) && ok;

    sq::scripting::ComponentBinder<MatchState> match(vm, module, "MatchState");
    match.property<&MatchState::blueScore>("blueScore")
        .property<&MatchState::orangeScore>("orangeScore")
        .property<&MatchState::phase>("phase")
        .property<&MatchState::countdown>("countdown")
        .property<&MatchState::clock>("clock")
        .property<&MatchState::overtime>("overtime");
    ok = define(vm, match) && ok;

    sq::scripting::ComponentBinder<sq::ecs::CameraComponent> camera(vm, module, "Camera");
    camera.property<&sq::ecs::CameraComponent::targetX>("targetX")
        .property<&sq::ecs::CameraComponent::targetY>("targetY")
        .property<&sq::ecs::CameraComponent::offsetX>("offsetX")
        .property<&sq::ecs::CameraComponent::offsetY>("offsetY")
        .property<&sq::ecs::CameraComponent::zoom>("zoom");
    ok = define(vm, camera) && ok;

    sq::scripting::ComponentBinder<CameraRig> rig(vm, module, "CameraRig");
    rig.property<&CameraRig::car>("car")
        .property<&CameraRig::ball>("ball")
        .property<&CameraRig::phase>("phase")
        .property<&CameraRig::viewWidth>("viewWidth")
        .property<&CameraRig::viewHeight>("viewHeight")
        .property<&CameraRig::boundsLeft>("boundsLeft")
        .property<&CameraRig::boundsTop>("boundsTop")
        .property<&CameraRig::boundsRight>("boundsRight")
        .property<&CameraRig::boundsBottom>("boundsBottom");
    ok = define(vm, rig) && ok;

    return ok;
}

bool installScriptBindings(sq::scripting::ScriptSystem& scripts) {
    // The car scripts read the controls through `core/Input`.
    sq::input::addInputScripting(scripts);
    const bool ok = registerComponentClasses(scripts.getVm());
    scripts.addBinderReplay([](sq::scripting::WrenVM& vm) { (void)registerComponentClasses(vm); });
    return ok;
}

}  // namespace rlss::game
